def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = 0
    my_defects = 0
    for me, opp in history:
        if opp == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    last_me, last_opp = history[-1]
    opp_rate = opp_defects / n

    # Endgame: if opponent has been very cooperative, defect in the last two rounds
    if n >= 98:
        if opp_rate <= 0.15:
            return 'D'
        if n >= 99:
            return 'D'

    # If opponent has never defected, cooperate but rarely test after round 50
    if opp_defects == 0:
        if n >= 50 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect
    if opp_rate > 0.5:
        return 'D'

    # Forgiving Tit-for-Tat with adaptive forgiveness based on opponent's defection rate
    if last_opp == 'D':
        # If opponent defected in the last two rounds, defect
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        # Otherwise, forgive more often when their overall defection rate is low
        if opp_rate < 0.2:
            return 'C' if rng.random() < 0.7 else 'D'
        elif opp_rate < 0.4:
            return 'C' if rng.random() < 0.4 else 'D'
        else:
            return 'D'
    else:
        # Opponent cooperated last round
        if last_me == 'D':
            # We defected last round, cooperate to restore unless opponent is a known defector
            if opp_rate < 0.3:
                return 'C'
            else:
                return 'C' if rng.random() < 0.8 else 'D'
        # Default: cooperate
        return 'C'
